{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled for the S3 bucket. Without versioning, data recovery in case of accidental deletion or overwrites is not possible."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "Access logging is not enabled for the S3 bucket. Without logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration. Without lifecycle rules, old or unused objects may accumulate, increasing storage costs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }

  versioning {
    enabled = true
  }

  logging {
    target_bucket = aws_s3_bucket.log_bucket.id
    target_prefix = "logs/"
  }

  public_access_block {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }

  lifecycle_rule {
    id      = "expire-old-objects"
    enabled = true

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      days = 30
    }
  }
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "roger-bucket-logs"
  acl    = "log-delivery-write"
}",
  "fix_summary": "Enabled versioning, access logging, public access block, and lifecycle configuration for the S3 bucket. Added a logging bucket for access logs."
}
